"""Generated from the game's data tables. Do not edit by hand."""

from typing import NamedTuple


class EscortSpec(NamedTuple):
    borg: int
    cap: int                             # live-slot cap relative to the leader
    flags: int                           # the +0x0E flags byte
    offset: tuple[float, float, float]   # (dx, dy, dz) from the leader


class IsolatedWave(NamedTuple):
    leader_cell: int                     # waits for an empty field
    partner_cell: int                    # follows at once; nothing spawns afterwards


class Queue(NamedTuple):
    pointer: int                         # vanilla pointer of enemy queue 2
    records: int                         # 0x20-byte records, loop marks and terminator included


